window.AUTH=window.AUTH||{};window.AUTH["24-320"]={"d":"24-320","id":"2024/24-320","n":"Soto v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Simon A. Soto","date":"2025-03-03","url":"https://www.supremecourt.gov/DocketPDF/24/24-320/351077/20250303172155989_Soto%20Petitioner%20Brief%20final.pdf","side":"pet","n":25},{"k":"respondent","label":"Brief of respondent United States","date":"2025-04-02","url":"https://www.supremecourt.gov/DocketPDF/24/24-320/354650/20250402220740541_24-320bsUnitedStates.pdf","side":"res","n":222},{"k":"reply","label":"Reply of petitioner Simon A. Soto","date":"2025-04-18","url":"https://www.supremecourt.gov/DocketPDF/24/24-320/355987/20250418100113884_Soto%20-%20Merits%20Reply%20Brief_A.pdf","side":"pet","n":12}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/605us2r42_k5fl.pdf","tr":true,"items":[{"t":"case","label":"Adams v. Hinchman","cite":"154 F.3d 420","y":1998,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/154/420/","by":{"0":"23","1":"32","2":"8"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"by":{"0":"38"}},{"t":"case","label":"Bostock v. Clayton Cnty.","cite":"590 U.S. 644","y":2020,"id":"2019/17-1618","sc":1,"by":{"0":"42"}},{"t":"case","label":"CFTC v. Schor","cite":"478 U.S. 833","y":1986,"id":"1985/85-621","sc":1,"by":{"0":"45"}},{"t":"case","label":"Cooke v. United States","cite":"91 U.S. 389","y":1875,"id":"scdb/1875-019","sc":1,"by":{"0":"37","1":"7, 38"}},{"t":"case","label":"Devlin v. Berry","cite":"26 F. Supp. 3d 74","y":2014,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/26/74/","by":{"0":"23"}},{"t":"case","label":"FAA v. Cooper","cite":"566 U.S. 284","y":2012,"id":"2011/10-1024","sc":1,"by":{"0":"37, 38"},"q":[{"src":"brief","b":0,"text":"Congress need not state its intent [to waive sovereign immunity] in any particular way. We have never required that Congress use magic words.","cite":"566 U.S. 284, 291"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"[w]e have never required that Congress use magic words.","cite":"566 U. S. 284, 291"}]},{"t":"case","label":"Fishgold v. Sullivan Drydock & Repair Corp.","cite":"328 U.S. 275","y":1946,"id":"scdb/1945-102","sc":1,"by":{"0":"39"}},{"t":"case","label":"Hernandez v. Dep’t of Air Force","cite":"498 F.3d 1328","y":2007,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/498/1328/","by":{"0":"26, 35","1":"16, 41, 42"},"q":[{"src":"argument","who":"Ms. Flint","text":"One is the Uniformed Services Employment and Reemployment Rights Act discussed by the Federal Circuit in Hernandez versus Department of Air Force."}]},{"t":"case","label":"Hobbs v. McLean","cite":"117 U.S. 567","y":1886,"id":"scdb/1885-195","sc":1,"by":{"0":"22","1":"4"},"q":[{"src":"brief","b":0,"text":"a right to demand money from the United States . . . which can be presented by the claimant to some department or officer of the United States for payment, or may be prosecuted in the court of claims.","cite":"117 U.S. 567, 575"},{"src":"brief","b":1,"text":"a right to demand money from the United States.","cite":"117 U.S. 567, 575"}]},{"t":"case","label":"Ill. Sur. Co. v. United States","cite":"240 U.S. 214","y":1916,"id":"scdb/1915-092","sc":1,"by":{"0":"22, 32","1":"6, 24, 38"},"q":[{"src":"brief","b":0,"text":"The word ‘settlement,’ in connection with public transactions and accounts, has been used from the beginning to describe administrative determination of the amount due.","cite":"240 U.S. 214, 219"},{"src":"brief","b":1,"text":"The word ‘settlement’ in connection with public transactions and accounts has been used from the beginning to describe administrative determination of the amount due.","cite":"240 U.S. 214, 219"}]},{"t":"case","label":"King v. St. Vincent's Hosp.","cite":"502 U.S. 215","y":1991,"id":"1991/90-889","sc":1,"by":{"0":"38, 39"},"q":[{"src":"brief","b":0,"text":"[i]t is presumable that Congress legislate[d] with knowledge","cite":"502 U.S. at 220 n.9"}]},{"t":"case","label":"Lac du Flambeau Band of Lake Superior Chippewa Indians v. Coughlin","cite":"599 U.S. 382","y":2023,"id":"2022/22-227","sc":1,"by":{"0":"37"},"q":[{"src":"argument","who":"Ms. Flint","text":"Well, in this Court's recent cases, in Lac du Flambeau from a couple terms ago, in Kurtz from last term, in the sovereign immunity context, the Court has said that's wrong."},{"src":"argument","who":"Ms. Flint","text":"The Court rejected a very similar argument in Lac du Flambeau about whether the Bankruptcy Code abrogated tribal sovereign immunity. The argument was that other statutes had made express reference to tribal sovereign immunity, and the Court said Congress is entitled to do it differently this time."}]},{"t":"case","label":"McNeil v. United States","cite":"78 Fed. Cl. 211","y":2007,"url":"https://www.courtlistener.com/c/Fed.%20Cl./78/211/","by":{"0":"35, 36"}},{"t":"case","label":"Mobil Oil Corp. v. Higginbotham","cite":"436 U.S. 618","y":1978,"id":"1977/76-1726","sc":1,"by":{"0":"42"}},{"t":"case","label":"Off. of Pers. Mgmt. v. Richmond","cite":"496 U.S. 414","y":1990,"id":"1989/88-1943","sc":1,"by":{"0":"23","1":"21"},"q":[{"src":"brief","b":0,"text":"adjudicate[d] each individual money claim against the United States.","cite":"496 U.S. 414, 430"}]},{"t":"case","label":"Paige v. United States","cite":"159 Fed. Cl. 383","y":2022,"url":"https://www.courtlistener.com/c/Fed.%20Cl./159/383/","by":{"0":"23","1":"34"}},{"t":"case","label":"Robinson v. Shell Oil Co.","cite":"519 U.S. 337","y":1997,"id":"1996/95-1376","sc":1,"by":{"0":"42"}},{"t":"case","label":"Rudisill v. McDonough","cite":"601 U.S. 294","y":2024,"id":"2023/22-888","sc":1,"by":{"0":"38, 39","1":"46, 47"},"q":[{"src":"brief","b":1,"text":"the canon’s seemingly nonexistent impact on this Court’s decisions.","cite":"601 U.S. 294, 316"}]},{"t":"case","label":"Sandstrom v. Principi","cite":"358 F.3d 1376","y":2004,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/358/1376/","by":{"0":"43","1":"44"}},{"t":"case","label":"Smith v. Gober","cite":"14 Vet. App. 227","y":2000,"url":"https://www.courtlistener.com/c/Vet.%20App./14/227/","by":{"0":"43"}},{"t":"case","label":"Soto v. United States","cite":"92 F.4th 1094","y":2024,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.4th/92/1094/","by":{"0":"21, 24, 25, 34, 35"}},{"t":"const","label":"Article I, Section 8, Clause 1","clauses":[["taxing-spending","Taxing and Spending Clause"]],"text":"The Congress shall have Power To lay and collect Taxes, Duties, Imposts and Excises, to pay the Debts and provide for the common Defence and general Welfare of the United States; but all Duties, Imposts and Excises shall be uniform throughout the United States;","by":{"0":"21","1":"21"}},{"t":"const","label":"Article I, Section 9, Clause 7","clauses":[["appropriations","Appropriations Clause"]],"text":"No Money shall be drawn from the Treasury, but in Consequence of Appropriations made by Law; and a regular Statement and Account of the Receipts and Expenditures of all public Money shall be published from time to time.","by":{"0":"21"}},{"t":"const","label":"Article IV, Section 3, Clause 2","clauses":[["property-clause","Territory and Property Clause"]],"text":"The Congress shall have Power to dispose of and make all needful Rules and Regulations respecting the Territory or other Property belonging to the United States; and nothing in this Constitution shall be so construed as to Prejudice any Claims of the United States, or of any particular State.","by":{"0":"21"}},{"t":"case","label":"Arellano v. McDonough","cite":"598 U.S. 1","y":2023,"id":"2022/21-432","sc":1,"by":{"1":"45, 47"}},{"t":"case","label":"Chickasaw Nation v. United States","cite":"534 U.S. 84","y":2001,"id":"2001/00-507","sc":1,"by":{"1":"47"}},{"t":"case","label":"Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"by":{"1":"46"}},{"t":"case","label":"Hood v. AU Optronics Corp.","cite":"571 U.S. 161","y":2014,"id":"2013/12-1036","sc":1,"by":{"1":"32, 32"},"q":[{"src":"brief","b":1,"text":"presume[s] that ‘Congress is aware of existing law when it passes legislation.’","cite":"571 U.S. 161, 169"}]},{"t":"case","label":"Kemp v. United States","cite":"596 U.S. 528","y":2022,"id":"2021/21-5726","sc":1,"by":{"1":"34"},"q":[{"src":"brief","b":1,"text":"they ‘easily could have drafted language to that effect’","cite":"596 U.S. 528, 534"}]},{"t":"case","label":"Loper Bright Enters. v. Raimondo","cite":"603 U.S. 369","y":2024,"id":"2023/22-451","sc":1,"by":{"1":"28"}},{"t":"case","label":"Maine Cmty. Health Options v. United States","cite":"590 U.S. 296","y":2020,"id":"2019/18-1023","sc":1,"by":{"1":"28"}},{"t":"case","label":"Petrella v. Metro-Goldwyn-Mayer, Inc.","cite":"572 U.S. 663","y":2014,"id":"2013/12-1315","sc":1,"by":{"1":"23"}},{"t":"case","label":"Republic of Hungary v. Simon","cite":"145 S. Ct. 480","y":2025,"id":"2024/23-867","sc":1,"by":{"1":"32"}},{"t":"case","label":"Rotkiske v. Klemm","cite":"589 U.S. 8","y":2019,"id":"2019/18-328","sc":1,"by":{"1":"29","2":"13"},"q":[{"src":"brief","b":1,"text":"[a]textual judicial supplementation is particularly inappropriate.","cite":"589 U.S. 8, 14"}]},{"t":"case","label":"United States v. Corliss Steam-Engine Co.","cite":"91 U.S. 321","y":1876,"id":"scdb/1875-093","sc":1,"by":{"1":"21"}},{"t":"case","label":"United States v. Sherwood","cite":"312 US. 584","y":1941,"url":"https://www.courtlistener.com/c/US./312/584/","by":{"1":"21"}},{"t":"case","label":"Waetzig v. Halliburton Energy Servs., Inc.","cite":"145 S. Ct. 690","y":2025,"id":"2024/23-971","sc":1,"by":{"1":"32","2":"13"}},{"t":"case","label":"Williams v. United States","cite":"289 US. 553","y":1933,"url":"https://www.courtlistener.com/c/US./289/553/","by":{"1":"21"},"q":[{"src":"brief","b":1,"text":"function which belongs primarily to Congress.","cite":"289 US. 553, 569"}]},{"t":"law","label":"Pub. L. No. 97-258","url":"https://www.govinfo.gov/link/statute/96/970","by":{"1":"9"}},{"t":"law","label":"Pub. L. No. 103-329","url":"https://www.govinfo.gov/link/statute/108/2432","by":{"1":"32"}},{"t":"law","label":"Pub. L. No. 104-52","url":"https://www.govinfo.gov/link/plaw/104/public/52","by":{"1":"32"}},{"t":"law","label":"Pub. L. No. 107-314","url":"https://www.govinfo.gov/link/plaw/107/public/314","by":{"1":"9, 10"}},{"t":"usc","label":"29 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/29/201","by":{"1":"32"}},{"t":"usc","label":"28 U.S.C. § 2671","url":"https://www.law.cornell.edu/uscode/text/28/2671","by":{"1":"25"}},{"t":"usc","label":"28 U.S.C. § 2672","url":"https://www.law.cornell.edu/uscode/text/28/2672","by":{"1":"25"}},{"t":"law","label":"Pub. L. No. 106-398","url":"https://www.govinfo.gov/link/plaw/106/public/398","by":{"1":"8","2":"12"}},{"t":"usc","label":"10 U.S.C. § 2734","url":"https://www.law.cornell.edu/uscode/text/10/2734","subs":["(a)","(b)"],"by":{"1":"26, 26, 26"}},{"t":"usc","label":"10 U.S.C. § 2734b","url":"https://www.law.cornell.edu/uscode/text/10/2734b","subs":["(a)"],"by":{"1":"26"}},{"t":"law","label":"Pub. L. No. 93-604","url":"https://www.govinfo.gov/link/statute/88/1965","by":{"1":"8"}},{"t":"law","label":"Pub. L. No. 104-316","url":"https://www.govinfo.gov/link/plaw/104/public/316","by":{"1":"7"}},{"t":"law","label":"Pub. L. No. 104-53","url":"https://www.govinfo.gov/link/plaw/104/public/53","by":{"1":"7"}},{"t":"usc","label":"28 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/28/1346","subs":["(a)(2)"],"by":{"1":"14"}},{"t":"usc","label":"10 U.S.C. § 2731","url":"https://www.law.cornell.edu/uscode/text/10/2731","by":{"1":"26, 25"}},{"t":"usc","label":"10 U.S.C. § 2733","url":"https://www.law.cornell.edu/uscode/text/10/2733","subs":["(a)","(b)(1)"],"by":{"1":"26, 26"}},{"t":"usc","label":"10 U.S.C. § 2735","url":"https://www.law.cornell.edu/uscode/text/10/2735","by":{"1":"26"}},{"t":"usc","label":"10 U.S.C. § 2737","url":"https://www.law.cornell.edu/uscode/text/10/2737","subs":["(a)","(e)"],"by":{"1":"26, 26"}},{"t":"law","label":"Pub. L. No. 104-201","url":"https://www.govinfo.gov/link/plaw/104/public/201","by":{"1":"9"}},{"t":"law","label":"Pub. L. No. 105-85","url":"https://www.govinfo.gov/link/plaw/105/public/85","by":{"1":"9"}},{"t":"law","label":"Pub. L. No. 108-136","url":"https://www.govinfo.gov/link/plaw/108/public/136","by":{"1":"12"}},{"t":"law","label":"Pub. L. No. 110-181","url":"https://www.govinfo.gov/link/plaw/110/public/181","by":{"1":"10"}},{"t":"law","label":"Pub. L. No. 118-159","url":"https://www.govinfo.gov/link/plaw/118/public/159","by":{"1":"31"}},{"t":"usc","label":"38 U.S.C. § 4301","url":"https://www.law.cornell.edu/uscode/text/38/4301","by":{"1":"41"}},{"t":"usc","label":"10 U.S.C. § 1047","url":"https://www.law.cornell.edu/uscode/text/10/1047","subs":["(a)"],"by":{"1":"39"}},{"t":"usc","label":"10 U.S.C. § 1052","url":"https://www.law.cornell.edu/uscode/text/10/1052","subs":["(a)"],"by":{"1":"39, 40"}},{"t":"usc","label":"10 U.S.C. § 1053","url":"https://www.law.cornell.edu/uscode/text/10/1053","subs":["(a)(1)","(b)","(c)"],"by":{"1":"39, 40, 40"}},{"t":"usc","label":"10 U.S.C. § 1059","url":"https://www.law.cornell.edu/uscode/text/10/1059","subs":["(a)","(d)","(m)"],"by":{"1":"39, 39, 37, 40"}},{"t":"usc","label":"10 U.S.C. § 1124","url":"https://www.law.cornell.edu/uscode/text/10/1124","subs":["(a)","(e)","(g)"],"by":{"1":"39, 40, 40"}},{"t":"usc","label":"10 U.S.C. § 1174","url":"https://www.law.cornell.edu/uscode/text/10/1174","subs":["(a)(2)"],"stext":{"head":"§1174. Separation pay upon involuntary discharge or release from active duty","paras":[[0,"(a) Regular Officers.—(1) A regular officer who is discharged under chapter 36 of this title (except under section 630(1)(A) or 643 of such chapter) or under section 580 or 8372 of this title and who has completed six or more, but less than twenty, years of active service immediately before that discharge is entitled to separation pay computed under subsection (d)(1)."],[0,"(2) A regular commissioned officer of the Army, Navy, Air Force or Marine Corps who is discharged under section 630(1)(A), 643, or 1186 of this title, and a regular warrant officer of the Army, Navy, Air Force or Marine Corps who is separated under section 1165 or 1166 of this title, who has completed six or more, but less than twenty, years of active service immediately before that discharge or separation is entitled to separation pay computed under subsection (d)(1) or (d)(2), as determined by the Secretary of the military department concerned, unless the Secretary concerned determines that the conditions under which the officer is discharged or separated do not warrant payment of such pay."],[0,"(3) Notwithstanding paragraphs (1) and (2), an officer discharged under any provision of chapter 36 of this title for twice failing of selection for promotion to the next higher grade is not entitled to separation pay under this section if either (or both) of those failures of selection for promotion was by the action of a selection board to which the officer submitted a request in writing not to be selected for promotion or who otherwise directly caused his nonselection through written communication to the Board under section 614(b) of this title."],[0,"(4) Notwithstanding paragraphs (1) and (2), an officer who is subject to discharge under any provision of chapter 36 of this title or under section 580 or 8372 of this title by reason of having twice failed of selection for promotion to the next higher grade is not entitled to separation pay under this section if that officer, after such second failure of selection for promotion, is selected for, and declines, continuation on active duty for a period that is equal to or more than the amount of service required to qualify the officer for retirement."],[0,"(b) Regular Enlisted Members.—(1) A regular enlisted member of an armed force who is discharged involuntarily or as the result of the denial of the reenlistment of the member and who has completed six or more, but less than 20, years of active service immediately before that discharge is entitled to separation pay computed under subsection (d) unless the Secretary concerned determines that the conditions under which the member is discharged do not warrant payment of such pay."],[0,"(2) Separation pay of an enlisted member shall be computed under paragraph (1) of subsection (d), except that such pay shall be computed under paragraph (2) of such subsection in the case of a member who is discharged under criteria prescribed by the Secretary of Defense."],[0,"(c) Other Members.—(1) Except as provided in paragraphs (2) and (3), a member of an armed force other than a regular member who is discharged or released from active duty and who has completed six or more, but fewer than 20, years of active service immediately before that discharge or release is entitled to separation pay computed under subsection (d)(1) or (d)(2), as determined by the Secretary concerned, if—"],[1,"(A) the member's discharge or release from active duty is involuntary; or"],[1,"(B) the member was not accepted for an additional tour of active duty for which he volunteered."],[0,"(2) If the Secretary concerned determines that the conditions under which a member described in paragraph (1) is discharged or separated do not warrant separation pay under this section, that member is not entitled to that pay."],[0,"(3) A member described in paragraph (1) who was not on the active-duty list when discharged or separated is not entitled to separation pay under this section unless such member had completed at least six years of continuous active duty immediately before such discharge or release. For purposes of this paragraph, a period of active duty is continuous if it is not interrupted by a break in service of more than 30 days."],[0,"(4) In the case of an officer who is subject to discharge or release from active duty under a law or regulation requiring that an officer who has failed of selection for promotion to the next higher grade for the second time be discharged or released from active duty and who, after such second failure of selection for promotion, is selected for, and declines, continuation on active duty—"],[1,"(A) if the period of time for which the officer was selected for continuation on active duty is less than the amount of service that would be required to qualify the officer for retirement, the officer's discharge or release from active duty shall be considered to be involuntary for purposes of paragraph (1)(A); and"],[1,"(B) if the period of time for which the officer was selected for continuation on active duty is equal to or more than the amount of service that would be required to qualify the officer for retirement, the officer's discharge or release from active duty shall not be considered to be involuntary for the purposes of paragraph (1)(A)."],[0,"(d) Amount of Separation Pay.—The amount of separation pay which may be paid to a member under this section is—"],[1,"(1) 10 percent of the product of (A) his years of active service, and (B) 12 times the monthly basic pay to which he was entitled at the time of his discharge or release from active duty; or"],[1,"(2) one-half of the amount computed under clause (1)."],[0,"(e) Requirement for Service in Ready Reserve; Exceptions To Eligibility.—(1)(A) As a condition of receiving separation pay under this section, a person otherwise eligible for that pay shall be required to enter into a written agreement with the Secretary concerned to serve in the Ready Reserve of a reserve component for a period of not less than three years following the person's discharge or release from active duty. If the person has a service obligation under section 651 of this title or under any other provision of law that is not completed at the time the person is discharged or released from active duty, the three-year obligation under this subsection shall begin on the day after the date on which the person completes the person's obligation under such section or other provision of law."],[0,"(B) Each person who enters into an agreement referred to in subparagraph (A) who is not already a Reserve of an armed force and who is qualified shall, upon such person's discharge or release from active duty, be enlisted or appointed, as appropriate, as a Reserve and be transferred to a reserve component."],[0,"(2) A member who is discharged or released from active duty is not eligible for separation pay under this section if the member—"],[1,"(A) is discharged or released from active duty at his request;"],[1,"(B) is discharged or released from active duty during an initial term of enlistment or an initial period of obligated service, unless the member is an officer discharged or released under the authority of section 647 of this title;"],[1,"(C) is released from active duty for training; or"],[1,"(D) upon discharge or release from active duty, is immediately eligible for retired or retainer pay based on his military service."],[0,"(f) Counting Fractional Years of Service.—In determining a member's years of active service for the purpose of computing separation pay under this section, each full month of service that is in addition to the number of full years of service creditable to the member is counted as one-twelfth of a year and any remaining fractional part of a month is disregarded."],[0,"(g) Coordination With Other Separation or Severance Pay Benefits.—A period for which a member has previously received separation pay under this section or severance pay or readjustment pay under any other provision of law based on service in the armed forces may not be included in determining the years of service that may be counted in computing the separation pay of the member under this section."],[0,"(h) Coordination With Retired or Retainer Pay and Disability Compensation.—(1) A member who has received separation pay under this section, or separation pay, severance pay, or readjustment pay under any other provision of law, based on service in the armed forces, and who later qualifies for retired or retainer pay under this title or title 14 shall have deducted from each payment of such retired or retainer pay an amount, in such schedule of monthly installments as the Secretary of Defense shall specify, taking into account the financial ability of the member to pay and avoiding the imposition of undue financial hardship on the member and member's dependents, until the total amount deducted is equal to the total amount of separation pay, severance pay, and readjustment pay so paid."],[0,"(2) A member who has received separation pay under this section, or severance pay or readjustment pay under any other provision of law, based on service in the armed forces shall not be deprived, by reason of his receipt of such separation pay, severance pay, or readjustment pay, of any disability compensation to which he is entitled under the laws administered by the Department of Veterans Affairs, but there shall be deducted from that disability compensation an amount equal to the total amount of separation pay, severance pay, and readjustment pay received, less the amount of Federal income tax withheld from such pay (such withholding being at the flat withholding rate for Federal income tax withholding, as in effect pursuant to regulations prescribed under chapter 24 of the Internal Revenue Code of 1986). Notwithstanding the preceding sentence, no deduction may be made from disability compensation for the amount of any separation pay, severance pay, or readjustment pay received because of an earlier discharge or release from a period of active duty if the disability which is the basis for that disability compensation was incurred or aggravated during a later period of active duty."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/10/1174?type=usc&year=mostrecent&link-type=html"},"by":{"1":"37, 38, 40","2":"19"}},{"t":"usc","label":"10 U.S.C. § 1175","url":"https://www.law.cornell.edu/uscode/text/10/1175","subs":["(a)(1)","(b)(3)","(g)"],"by":{"1":"39, 40, 40"}},{"t":"usc","label":"10 U.S.C. § 1175a","url":"https://www.law.cornell.edu/uscode/text/10/1175a","subs":["(a)","(b)(1)(D)","(b)(3)","(k)"],"by":{"1":"39, 40, 40, 37, 38, 46"}},{"t":"usc","label":"10 U.S.C. § 1201","url":"https://www.law.cornell.edu/uscode/text/10/1201","subs":["(a)","(b)"],"by":{"1":"13, 36, 37, 37"}},{"t":"usc","label":"10 U.S.C. § 1202","url":"https://www.law.cornell.edu/uscode/text/10/1202","by":{"1":"13, 36"}},{"t":"usc","label":"10 U.S.C. § 1204","url":"https://www.law.cornell.edu/uscode/text/10/1204","by":{"1":"36"}},{"t":"usc","label":"10 U.S.C. § 1205","url":"https://www.law.cornell.edu/uscode/text/10/1205","by":{"1":"36"}},{"t":"usc","label":"10 U.S.C. § 1216","url":"https://www.law.cornell.edu/uscode/text/10/1216","subs":["(a)","(b)","(d)"],"by":{"1":"40, 37, 37"}},{"t":"usc","label":"10 U.S.C. § 1401","url":"https://www.law.cornell.edu/uscode/text/10/1401","by":{"1":"36"}},{"t":"usc","label":"10 U.S.C. § 1413a","url":"https://www.law.cornell.edu/uscode/text/10/1413a","subs":["(a)","(b)","(b)(1)","(b)(2)","(b)(3)(B)","(c)","(d)","(e)","(h)","(i)"],"stext":{"head":"§1413a. Combat-related special compensation","paras":[[0,"(a) Authority.—The Secretary concerned shall pay to each eligible combat-related disabled uniformed services retiree who elects benefits under this section a monthly amount for the combat-related disability of the retiree determined under subsection (b)."],[0,"(b) Amount.—"],[1,"(1) Determination of monthly amount.—Subject to paragraphs (2) and (3), the monthly amount to be paid an eligible combat-related disabled uniformed services retiree under subsection (a) for any month is the amount of compensation to which the retiree is entitled under title 38 for that month, determined without regard to any disability of the retiree that is not a combat-related disability."],[1,"(2) Maximum amount.—The amount paid to an eligible combat-related disabled uniformed services retiree for any month under paragraph (1) may not exceed the amount of the reduction in retired pay that is applicable to the retiree for that month under sections 5304 and 5305 of title 38."],[1,"(3) Special rules for chapter 61 disability retirees.—"],[2,"(A) General rule.—In the case of an eligible combat-related disabled uniformed services retiree who is retired under chapter 61 of this title, the amount of the payment under paragraph (1) for any month may not, when combined with the amount of retired pay payable to the retiree after any such reduction under sections 5304 and 5305 of title 38, cause the total of such combined payment to exceed the amount of retired pay to which the member would have been entitled under any other provision of law based upon the member's service in the uniformed services if the member had not been retired under chapter 61 of this title."],[2,"(B) Special rule for retirees with fewer than 20 years of service.—In the case of an eligible combat-related disabled uniformed services retiree who is retired under chapter 61 of this title with fewer than 20 years of creditable service, the amount of the payment under paragraph (1) for any month may not, when combined with the amount of retired pay payable to the retiree after any such reduction under sections 5304 and 5305 of title 38, cause the total of such combined payment to exceed the amount equal to the retired pay percentage (determined for the member under section 1409(b) of this title) of the member's years of creditable service multiplied by the member's retired pay base under section 1406(b)(1) or 1407 of this title, whichever is applicable to the member."],[0,"(c) Eligible Retirees.—For purposes of this section, an eligible combat-related disabled uniformed services retiree referred to in subsection (a) is a member of the uniformed services who—"],[1,"(1) is entitled to retired pay (other than by reason of section 12731b of this title); and"],[1,"(2) has a combat-related disability."],[0,"(d) Procedures.—The Secretary of Defense shall prescribe procedures and criteria under which a disabled uniformed services retiree may apply to the Secretary of a military department to be considered to be an eligible combat-related disabled uniformed services retiree. Such procedures shall apply uniformly throughout the Department of Defense."],[0,"(e) Combat-Related Disability.—In this section, the term \"combat-related disability\" means a disability that is compensable under the laws administered by the Secretary of Veterans Affairs and that—"],[1,"(1) is attributable to an injury for which the member was awarded the Purple Heart; or"],[1,"(2) was incurred (as determined under criteria prescribed by the Secretary of Defense)—"],[2,"(A) as a direct result of armed conflict;"],[2,"(B) while engaged in hazardous service;"],[2,"(C) in the performance of duty under conditions simulating war; or"],[2,"(D) through an instrumentality of war."],[0,"(f) Coordination With Concurrent Receipt Provision.—Subsection (d) of section 1414 of this title provides for coordination between benefits under that section and under this section."],[0,"(g) Status of Payments.—Payments under this section are not retired pay."],[0,"(h) Source of Payments.—Payments under this section for a member of the Army, Navy, Air Force, Marine Corps, or Space Force shall be paid from the Department of Defense Military Retirement Fund. Payments under this section for any other member for any fiscal year shall be paid out of funds appropriated for pay and allowances payable by the Secretary concerned for that fiscal year."],[0,"(i) Other Definitions.—In this section:"],[1,"(1) The term \"service-connected\" has the meaning given such term in section 101 of title 38."],[1,"(2) The term \"retired pay\" includes retainer pay, emergency officers' retirement pay, and naval pension."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/10/1413a?type=usc&year=mostrecent&link-type=html"},"by":{"1":"36, 36, 36, 36, 36, 36, 36, 36, 36, 36, 36, 36"},"q":[{"src":"brief","b":1,"text":"[t]he Secretary concerned shall pay to each eligible combat-related disabled uniformed ser- 3 Initially, CRSC entitlement was limited to retirees whose combatrelated disabilities were rated at least 60%, except where a disability was related to an injury for which the individual received a Purple Heart. See 2003 NDAA § 636, 116 Stat. 2574. Congress has since eliminated that requirement. See National Defense Authorization Act for Fiscal Year 2004, Pub. L. No. 108-136, § 642, 117 Stat. 1516 (2003). vices retiree who elects benefits under this section a monthly amount for the combat-related disability of the retiree.","cite":"10 U.S.C. 1413a(a)"},{"src":"brief","b":1,"text":"shall prescribe procedures and criteria under which a disabled uniformed services retiree may apply to the Secretary of a military department to be considered to be an eligible combat-related disabled uniformed services retiree.","cite":"10 U.S.C. 1413a(d)"},{"src":"argument","who":"Ms. Flint","text":"Right. Yes, Justice Thomas. The government has pointed to a number of statutes that it says have some similarities to Section 1413a."},{"src":"argument","who":"Ms. Flint","text":"Of course, none of these statutes are part of this case because the government's theory is that the Court should not read Section 1413a literally because of the risk that these other statutes will create a destabilization in their terms of military pay."},{"src":"argument","who":"Ms. Flint","text":"In Section 1413a, it is best read to authorize determination of validity and amount due. Section -- the Barring Act, you know, if -- if another statute authorizes that, the Barring Act doesn't apply."}]},{"t":"usc","label":"10 U.S.C. § 1414","url":"https://www.law.cornell.edu/uscode/text/10/1414","subs":["(d)"],"by":{"1":"36, 36"}},{"t":"usc","label":"10 U.S.C. § 1448","url":"https://www.law.cornell.edu/uscode/text/10/1448","subs":["(d)(6)(A)","(e)(1)","(e)(2)"],"by":{"1":"36, 39, 39, 39, 39, 39"}},{"t":"usc","label":"10 U.S.C. § 1450","url":"https://www.law.cornell.edu/uscode/text/10/1450","by":{"1":"36, 37, 39"}},{"t":"usc","label":"10 U.S.C. § 1451","url":"https://www.law.cornell.edu/uscode/text/10/1451","by":{"1":"36"}},{"t":"usc","label":"10 U.S.C. § 1455","url":"https://www.law.cornell.edu/uscode/text/10/1455","subs":["(a)"],"by":{"1":"40"}},{"t":"usc","label":"10 U.S.C. § 1463","url":"https://www.law.cornell.edu/uscode/text/10/1463","subs":["(a)"],"by":{"1":"40"}},{"t":"usc","label":"10 U.S.C. § 1475","url":"https://www.law.cornell.edu/uscode/text/10/1475","subs":["(a)"],"stext":{"head":"§1475. Death gratuity: death of members on active duty or inactive duty training and of certain other persons","paras":[[0,"(a) Except as provided in section 1480 of this title, the Secretary concerned shall have a death gratuity paid to or for the survivor prescribed by section 1477 of this title, immediately upon receiving official notification of the death of—"],[1,"(1) a member of an armed force under his jurisdiction who dies while on active duty or while performing authorized travel to or from active duty;"],[1,"(2) a Reserve of an armed force who dies while on inactive duty training (other than work or study in connection with a correspondence course of an armed force or attendance, in an inactive status, at an educational institution under the sponsorship of an armed force or the Public Health Service);"],[1,"(3) any Reserve of an armed force who, when authorized or required by an authority designated by the Secretary, assumed an obligation to perform active duty for training, or inactive duty training (other than work or study in connection with a correspondence course of an armed force or attendance, in an inactive status, at an educational institution, under the sponsorship of an armed force or the Public Health Service), and who dies while traveling directly to or from that active duty for training or inactive duty training or while staying at the Reserve's residence, when so authorized by proper authority, during the period of such inactive duty training or between successive days of inactive duty training;"],[1,"(4) any member of a reserve officers' training corps who dies while performing annual training duty under orders, or while performing authorized travel to or from that annual training duty; or any applicant for membership in a reserve officers' training corps who dies while attending field training or a practice cruise under section 2104(b)(6)(B) of this title or while performing authorized travel to or from the place where the training or cruise is conducted; or a graduate of a reserve officers' training corps who has received a commission but has yet to receive a first duty assignment; or"],[1,"(5) a person who dies while traveling to or from or while at a place for final acceptance, or for entry upon active duty (other than for training), in an armed force, who has been ordered or directed to go to that place, and who—"],[2,"(A) has been provisionally accepted for that duty; or"],[2,"(B) has been selected, under the Military Selective Service Act (50 U.S.C. 3801 et seq.), for service in that armed force."],[0,"(b) This section does not apply to the survivors of persons who were temporary members of the Coast Guard Reserve at the time of their death."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/10/1475?type=usc&year=mostrecent&link-type=html"},"by":{"1":"31, 36, 31, 36"},"q":[{"src":"argument","who":"Ms. Flint","text":"Section 1479, which is the provision which we have read as potentially authorizing settlement, that relates only to immediate payment of death gratuities under Section 1475."}]},{"t":"usc","label":"10 U.S.C. § 1476","url":"https://www.law.cornell.edu/uscode/text/10/1476","subs":["(a)(1)","(a)(2)"],"by":{"1":"31, 31"}},{"t":"usc","label":"10 U.S.C. § 1479","url":"https://www.law.cornell.edu/uscode/text/10/1479","subs":["(1)","(2)"],"stext":{"head":"§1479. Death gratuity: delegation of determinations, payments","paras":[[0,"For the purpose of making immediate payments under section 1475 of this title, the Secretary concerned shall—"],[1,"(1) authorize the commanding officer of a territorial command, installation, or district in which a survivor of a person covered by that section is residing to determine the beneficiary eligible for the death gratuity; and"],[1,"(2) authorize a disbursing or certifying official of each of those commands, installations, or districts to make the payments to the beneficiary, or certify the payments due them, as the case may be."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/10/1479?type=usc&year=mostrecent&link-type=html"},"by":{"1":"31, 31"},"q":[{"src":"argument","who":"Ms. Flint","text":"So we identified one in our brief, the death gratuity statute, section 1479. That authorizes a -- for purposes of immediate payment of death gratuities, it authorizes a regional command to determine which -- whether a beneficiary is entitled to the death gratuity and certify the amount due."},{"src":"argument","who":"Ms. Flint","text":"Section 1479, which is the provision which we have read as potentially authorizing settlement, that relates only to immediate payment of death gratuities under Section 1475."}]},{"t":"usc","label":"10 U.S.C. § 1480","url":"https://www.law.cornell.edu/uscode/text/10/1480","subs":["(c)","(d)","(e)"],"by":{"1":"31, 31, 31, 31"},"q":[{"src":"brief","b":1,"text":"the date that is six years after the date of the death.","cite":"10 U.S.C. 1480(e)"}]},{"t":"usc","label":"10 U.S.C. § 1482","url":"https://www.law.cornell.edu/uscode/text/10/1482","subs":["(a)","(b)","(d)(2)","(e)(1)","(e)(2)"],"by":{"1":"39, 39, 39, 39, 39"}},{"t":"usc","label":"10 U.S.C. § 1591","url":"https://www.law.cornell.edu/uscode/text/10/1591","subs":["(a)"],"by":{"1":"37"}},{"t":"usc","label":"10 U.S.C. § 1593","url":"https://www.law.cornell.edu/uscode/text/10/1593","subs":["(a)","(d)"],"by":{"1":"39, 40"}},{"t":"usc","label":"10 U.S.C. § 1596","url":"https://www.law.cornell.edu/uscode/text/10/1596","subs":["(a)"],"by":{"1":"39"}},{"t":"usc","label":"10 U.S.C. § 2575","url":"https://www.law.cornell.edu/uscode/text/10/2575","subs":["(d)(1)"],"by":{"1":"27"}},{"t":"usc","label":"10 U.S.C. § 7311","url":"https://www.law.cornell.edu/uscode/text/10/7311","by":{"1":"36"}},{"t":"usc","label":"10 U.S.C. § 7314","url":"https://www.law.cornell.edu/uscode/text/10/7314","by":{"1":"40"}},{"t":"usc","label":"10 U.S.C. § 7361","url":"https://www.law.cornell.edu/uscode/text/10/7361","by":{"1":"36"}},{"t":"usc","label":"10 U.S.C. § 7801","url":"https://www.law.cornell.edu/uscode/text/10/7801","by":{"1":"25"}},{"t":"usc","label":"10 U.S.C. § 8321","url":"https://www.law.cornell.edu/uscode/text/10/8321","by":{"1":"36"}},{"t":"usc","label":"10 U.S.C. § 8333","url":"https://www.law.cornell.edu/uscode/text/10/8333","by":{"1":"36"}},{"t":"usc","label":"10 U.S.C. § 8821","url":"https://www.law.cornell.edu/uscode/text/10/8821","subs":["(b)"],"by":{"1":"25"}},{"t":"usc","label":"10 U.S.C. § 9311","url":"https://www.law.cornell.edu/uscode/text/10/9311","by":{"1":"36"}},{"t":"usc","label":"10 U.S.C. § 9361","url":"https://www.law.cornell.edu/uscode/text/10/9361","by":{"1":"36"}},{"t":"usc","label":"10 U.S.C. § 9801","url":"https://www.law.cornell.edu/uscode/text/10/9801","by":{"1":"25"}},{"t":"usc","label":"10 U.S.C. § 12731","url":"https://www.law.cornell.edu/uscode/text/10/12731","subs":["(a)","(b)"],"by":{"1":"36, 39, 39, 39"}},{"t":"usc","label":"10 U.S.C. § 12739","url":"https://www.law.cornell.edu/uscode/text/10/12739","by":{"1":"39"}},{"t":"usc","label":"24 U.S.C. § 420","url":"https://www.law.cornell.edu/uscode/text/24/420","subs":["(d)"],"by":{"1":"27, 27"}},{"t":"usc","label":"28 U.S.C. § 2401","url":"https://www.law.cornell.edu/uscode/text/28/2401","subs":["(b)"],"by":{"1":"25"}},{"t":"usc","label":"31 U.S.C. § 3702","url":"https://www.law.cornell.edu/uscode/text/31/3702","subs":["(a)","(a)(1)","(a)(1)(A)","(a)(2)","(a)(4)","(b)","(b)(1)","(b)(1)(A)","(b)(2)","(e)","(e)(1)"],"stext":{"head":"§3702. Authority to settle claims","paras":[[0,"(a) Except as provided in this chapter or another law, all claims of or against the United States Government shall be settled as follows:"],[1,"(1) The Secretary of Defense shall settle—"],[2,"(A) claims involving uniformed service members' pay, allowances, travel, transportation, payments for unused accrued leave, retired pay, and survivor benefits; and"],[2,"(B) claims by transportation carriers involving amounts collected from them for loss or damage incurred to property incident to shipment at Government expense."],[1,"(2) The Director of the Office of Personnel Management shall settle claims involving Federal civilian employees' compensation and leave."],[1,"(3) The Administrator of General Services shall settle claims involving expenses incurred by Federal civilian employees for official travel and transportation, and for relocation expenses incident to transfers of official duty station."],[1,"(4) The Director of the Office of Management and Budget shall settle claims not otherwise provided for by this subsection or another provision of law."],[0,"(b)(1) A claim against the Government presented under this section must contain the signature and address of the claimant or an authorized representative. The claim must be received by the official responsible under subsection (a) for settling the claim or by the agency that conducts the activity from which the claim arises within 6 years after the claim accrues except—"],[1,"(A) as provided in this chapter or another law; or"],[1,"(B) a claim of a State, the District of Columbia, or a territory or possession of the United States."],[0,"(2) When the claim of a member of the armed forces accrues during war or within 5 years before war begins, the claim must be received within 5 years after peace is established or within the period provided in paragraph (1) of this subsection, whichever is later."],[0,"(3) A claim that is not received in the time required under this subsection shall be returned with a copy of this subsection, and no further communication is required."],[0,"(c) One-Year Limit for Check Claims.—(1) Any claim on account of a Treasury check shall be barred unless it is presented to the agency that authorized the issuance of such check within 1 year after the date of issuance of the check or the effective date of this subsection, whichever is later."],[0,"(2) Nothing in this subsection affects the underlying obligation of the United States, or any agency thereof, for which a Treasury check was issued."],[0,"(d) The official responsible under subsection (a) for settling the claim shall report to Congress on a claim against the Government that is timely presented under this section that may not be adjusted by using an existing appropriation, and that the official believes Congress should consider for legal or equitable reasons. The report shall include recommendations of the official."],[0,"(e)(1) The Secretary of Defense may waive the time limitations set forth in subsection (b) or (c) in the case of a claim referred to in subsection (a)(1)(A). In the case of a claim by or with respect to a member of the uniformed services who is not under the jurisdiction of the Secretary of a military department, such a waiver may be made only upon the request of the Secretary concerned (as defined in section 101 of title 37)."],[0,"(2) Payment of a claim settled under subsection (a)(1)(A) shall be made from an appropriation that is available, for the fiscal year in which the payment is made, for the same purpose as the appropriation to which the obligation claimed would have been charged if the obligation had been timely paid, except that in the case of a claim for retired pay or survivor benefits, if the obligation claimed would have been paid from a trust fund if timely paid, the payment of the claim shall be made from that trust fund."],[0,"(3) This subsection does not apply to a claim in excess of $25,000."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/3702?type=usc&year=mostrecent&link-type=html"},"by":{"1":"14, 14, 14, 14, 14, 14, 14, 22, 22, 22, 22, 22","2":"10, 12, 16, 19"},"q":[{"src":"brief","b":1,"text":"claims involving uniformed service members’ pay, allowances, travel, transportation, payments for unused accrued leave, retired pay, and survivor benefits.","cite":"31 U.S.C. 3702(a)(1)(A)"},{"src":"brief","b":1,"text":"[e]xcept as provided in this chapter or another law.","cite":"31 U.S.C. 3702(a)"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"claims of or against the United States Government shall be settled.","cite":"31 U. S. C. § 3702(a)"}]},{"t":"usc","label":"31 U.S.C. § 3716","url":"https://www.law.cornell.edu/uscode/text/31/3716","by":{"1":"30"}},{"t":"usc","label":"31 U.S.C. § 3720D","url":"https://www.law.cornell.edu/uscode/text/31/3720D","by":{"1":"30"}},{"t":"usc","label":"31 U.S.C. § 3721","url":"https://www.law.cornell.edu/uscode/text/31/3721","subs":["(a)(3)","(b)(1)","(g)"],"by":{"1":"17, 25, 26, 26"},"q":[{"src":"brief","b":1,"text":"consider, determine, adjust, and dispose of a claim by disallowance or by complete or partial allowance.","cite":"31 U.S.C. 3721(a)(3)"}]},{"t":"usc","label":"31 U.S.C. § 3724","url":"https://www.law.cornell.edu/uscode/text/31/3724","subs":["(a)"],"by":{"1":"25"}},{"t":"usc","label":"31 U.S.C. § 3728","url":"https://www.law.cornell.edu/uscode/text/31/3728","by":{"1":"30"}},{"t":"usc","label":"32 U.S.C. § 715","url":"https://www.law.cornell.edu/uscode/text/32/715","subs":["(h)"],"by":{"1":"25"}},{"t":"usc","label":"37 U.S.C. § 203","url":"https://www.law.cornell.edu/uscode/text/37/203","subs":["(a)(1)"],"stext":{"head":"§203. Rates","paras":[[0,"(a)(1) The rates of monthly basic pay for members of the uniformed services within each pay grade are those prescribed in accordance with section 1009 of this title or as otherwise prescribed by law."],[0,"(2) Notwithstanding the rates of basic pay in effect at any time as provided by law, the rates of basic pay payable for commissioned officers in pay grades O–7 through O–⁠10 may not exceed the monthly equivalent of the rate of pay for level II of the Executive Schedule, and the rates of basic pay payable for all other officers and for enlisted members may not exceed the monthly equivalent of the rate of pay for level V of the Executive Schedule."],[0,"(b) While serving as a permanent professor at the United States Military Academy, the United States Naval Academy, or the United States Air Force Academy or as a member of the permanent commissioned teaching staff at the United States Coast Guard Academy, an officer who has over 36 years of service computed under section 205 of this title is, in addition to the pay and allowances to which he is otherwise entitled under this title, entitled to additional pay in the amount of $250 a month. This additional pay may not be used in the computation of retired pay."],[0,"(c) A cadet at the United States Military Academy, the United States Air Force Academy, or the Coast Guard Academy, or a midshipman at the United States Naval Academy, is entitled to monthly cadet pay, or midshipman pay, at the monthly rate equal to 35 percent of the basic pay of a commissioned officer in the pay grade O–1 with less than two years of service."],[0,"(d)(1) The basic pay of a commissioned officer who is in pay grade O–1, O–2, or O–3 and who is credited with a total of over four years' service described in paragraph (2) shall be computed in the same manner as the basic pay of a commissioned officer in the same pay grade who has been credited with over four years' active service as an enlisted member."],[0,"(2) Service to be taken into account for purposes of computing basic pay under paragraph (1) is as follows:"],[1,"(A) Active service as a warrant officer or as a warrant officer and an enlisted member."],[1,"(B) Service as a warrant officer, as an enlisted member, or as a warrant officer and an enlisted member, for which at least 1,460 points have been credited to the officer for the purposes of section 12732(a)(2) of title 10."],[0,"(e)(1) A student at the United States Military Academy Preparatory School, the United States Naval Academy Preparatory School, or the United States Air Force Academy Preparatory School who was selected to attend the preparatory school from civilian life is entitled to monthly student pay at the same rate as provided for cadets and midshipmen under subsection (c)."],[0,"(2) A student at a preparatory school referred to in paragraph (1) who, at the time of the student's selection to attend the preparatory school, was an enlisted member of the uniformed services shall receive monthly basic pay at the rate prescribed for the student's pay grade and years of service as an enlisted member or at the rate provided for cadets and midshipmen under subsection (c), whichever is greater."],[0,"(3) The monthly student pay of a student described in paragraph (1) shall be treated for purposes of the accrual charge for the Department of Defense Military Retirement Fund established under section 1461 of title 10 in the same manner as monthly cadet pay or midshipman pay under subsection (c)."],[0,"(f)(1) An officer candidate enrolled in the basic officer training program of the commissioned officer corps of the National Oceanic and Atmospheric Administration is entitled, while participating in such program, to monthly officer candidate pay at monthly rates equal to the basic pay of an enlisted member in the pay grade E–5 with less than two years of service."],[0,"(2) An individual who graduates from such program shall receive credit for the time spent participating in such program as if such time were time served while on active duty as a commissioned officer. If the individual does not graduate from such program, such time shall not be considered creditable for active duty or pay."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/37/203?type=usc&year=mostrecent&link-type=html"},"by":{"1":"36","2":"15"}},{"t":"usc","label":"37 U.S.C. § 204","url":"https://www.law.cornell.edu/uscode/text/37/204","subs":["(b)","(c)","(c)(3)","(i)(4)"],"by":{"1":"35, 40, 36, 40, 40"}},{"t":"usc","label":"37 U.S.C. § 205","url":"https://www.law.cornell.edu/uscode/text/37/205","by":{"1":"36"}},{"t":"usc","label":"37 U.S.C. § 206","url":"https://www.law.cornell.edu/uscode/text/37/206","subs":["(a)","(b)","(c)","(d)(2)"],"by":{"1":"35, 40, 40, 36, 38"}},{"t":"usc","label":"37 U.S.C. § 331","url":"https://www.law.cornell.edu/uscode/text/37/331","subs":["(a)","(b)(2)","(c)(1)","(d)","(h)"],"by":{"1":"39, 37, 38, 37, 46"}},{"t":"usc","label":"37 U.S.C. § 351","url":"https://www.law.cornell.edu/uscode/text/37/351","subs":["(d)"],"by":{"1":"30"}},{"t":"usc","label":"37 U.S.C. § 352","url":"https://www.law.cornell.edu/uscode/text/37/352","subs":["(a)","(g)"],"by":{"1":"39, 46"}},{"t":"usc","label":"37 U.S.C. § 356","url":"https://www.law.cornell.edu/uscode/text/37/356","subs":["(a)","(b)","(c)","(h)"],"by":{"1":"39, 38, 39, 39, 40"}},{"t":"usc","label":"37 U.S.C. § 372","url":"https://www.law.cornell.edu/uscode/text/37/372","subs":["(a)"],"by":{"1":"39"}},{"t":"usc","label":"37 U.S.C. § 402","url":"https://www.law.cornell.edu/uscode/text/37/402","subs":["(d)","(i)(1)"],"by":{"1":"39, 40"}},{"t":"usc","label":"37 U.S.C. § 402a","url":"https://www.law.cornell.edu/uscode/text/37/402a","subs":["(c)","(g)(1)"],"by":{"1":"39, 39"}},{"t":"usc","label":"37 U.S.C. § 405","url":"https://www.law.cornell.edu/uscode/text/37/405","subs":["(a)","(b)"],"by":{"1":"39, 38"}},{"t":"usc","label":"37 U.S.C. § 451","url":"https://www.law.cornell.edu/uscode/text/37/451","subs":["(a)(2)(H)"],"by":{"1":"37"}},{"t":"usc","label":"37 U.S.C. § 452","url":"https://www.law.cornell.edu/uscode/text/37/452","subs":["(a)"],"by":{"1":"40"}},{"t":"usc","label":"37 U.S.C. § 453","url":"https://www.law.cornell.edu/uscode/text/37/453","subs":["(a)","(h)"],"by":{"1":"39, 39"}},{"t":"usc","label":"37 U.S.C. § 910","url":"https://www.law.cornell.edu/uscode/text/37/910","subs":["(a)","(g)"],"by":{"1":"38, 39, 46"}},{"t":"usc","label":"38 U.S.C. § 515","url":"https://www.law.cornell.edu/uscode/text/38/515","subs":["(a)(2)"],"by":{"1":"25"}},{"t":"usc","label":"38 U.S.C. § 2008","url":"https://www.law.cornell.edu/uscode/text/38/2008","subs":["(c)"],"by":{"1":"25"}},{"t":"usc","label":"38 U.S.C. § 4324","url":"https://www.law.cornell.edu/uscode/text/38/4324","subs":["(c)(1)","(c)(2)"],"by":{"1":"42, 42"}},{"t":"usc","label":"38 U.S.C. § 5110","url":"https://www.law.cornell.edu/uscode/text/38/5110","subs":["(b)(1)","(b)(4)"],"by":{"1":"30, 44, 45"}},{"t":"usc","label":"38 U.S.C. § 5304","url":"https://www.law.cornell.edu/uscode/text/38/5304","by":{"1":"9"}},{"t":"usc","label":"38 U.S.C. § 5305","url":"https://www.law.cornell.edu/uscode/text/38/5305","by":{"1":"9"}},{"t":"usc","label":"39 U.S.C. § 2008","url":"https://www.law.cornell.edu/uscode/text/39/2008","subs":["(c)"],"by":{"1":"25"},"q":[{"src":"brief","b":1,"text":"the final settlement of all claims and litigation by or against","cite":"39 U.S.C. 2008(c)"}]},{"t":"usc","label":"41 U.S.C. § 604","url":"https://www.law.cornell.edu/uscode/text/41/604","by":{"1":"27"}},{"t":"usc","label":"41 U.S.C. § 7103","url":"https://www.law.cornell.edu/uscode/text/41/7103","subs":["(a)","(c)(1)","(d)","(g)"],"by":{"1":"27, 27, 27, 27, 27"}},{"t":"reg","label":"32 C.F.R. pt. 282","url":"https://www.ecfr.gov/current/title-32/part-282","by":{"1":"8","2":"22"}},{"t":"case","label":"Byrd v. United States","cite":"584 U.S. 395","y":2018,"id":"2017/16-1371","sc":1,"by":{"2":"8"}},{"t":"case","label":"Dep’t of Agric. Rural Dev. Rural Hous. Serv. v. Kirtz","cite":"601 U.S. 42","y":2024,"id":"2023/22-846","sc":1,"by":{"2":"21"},"q":[{"src":"brief","b":2,"text":"none of that means [the Court] may disregard the statute’s clear terms.","cite":"601 U.S. 42, 61"}]},{"t":"case","label":"Groff v. DeJoy","cite":"600 U.S. 447","y":2023,"id":"2022/22-174","sc":1,"by":{"2":"13"},"q":[{"src":"brief","b":2,"text":"[S]tatutory interpretation must begin with, and ultimately heed, what a statute actually says.","cite":"600 U.S. 447, 468"}]},{"t":"case","label":"Intel Corp. Inv. Pol’y Comm. v. Sulyma","cite":"589 U.S. 178","y":2020,"id":"2019/18-1116","sc":1,"by":{"2":"13"}}]};